/**
 * @fileoverview Test the usage of a deprecated config
 * @author Sencha
 */
'use strict';

// ------------------------------------------------------------------------------
// Requirements
// ------------------------------------------------------------------------------

const rule = require('../../../lib/rules/no-deprecated-config-usage'),
    RuleTester = require('eslint').RuleTester;

// ------------------------------------------------------------------------------
// Tests
// ------------------------------------------------------------------------------

const ruleTester = new RuleTester();
ruleTester.run('no-deprecated-config-usage', rule, {

    valid: [
        {
            settings: {
                extjs: {
                    fromVersion: '4.1',
                    toVersion: '7.9.0'
                }
            },
            code: `
                Ext.define('MyCustomApp.Application', {
                    name: 'MyCustomApp',
                    extend: 'Ext.app.Application',
                    quickTips: true
                });
            `
        }
    ],

    invalid: [
        {
            settings: {
                extjs: {
                    toolkit: 'classic',
                    fromVersion: '4.1',
                    toVersion: '7.9.0'
                }
            },
            code: `
                Ext.define('MyCustomGrid', {
                    extend: 'Ext.grid.Panel',
                    multiSelect: true
                });

                Ext.create('Ext.Container', {
                    items: [{
                        xtype: 'grid',
                        simpleSelect: true
                    }]
                });
            `,
            output: `
                Ext.define('MyCustomGrid', {
                    extend: 'Ext.grid.Panel',
                    selModel: {mode: "MULTI"}
                });

                Ext.create('Ext.Container', {
                    items: [{
                        xtype: 'grid',
                        selModel: {mode: "SIMPLE"}
                    }]
                });
            `,
            errors: [
                { message: /Usage of deprecated config 'multiSelect' found for 'Ext.grid.Panel'.*/ },
                { message: /Usage of deprecated config 'simpleSelect' found for 'Ext.grid.Panel'.*/ }
            ]
        },
        {
            settings: {
                extjs: {
                    fromVersion: '4.1',
                    toVersion: '7.9.0'
                }
            },
            code: `
                Ext.define('User', {
                    extend: 'Ext.data.Model',
                    fields: [
                        'name', 'email',
                        {
                            name: 'age',
                            type: 'int',
                            useNull: true
                        },
                        {
                            name: 'gender',
                            type: 'abc',
                            defaultValue: 'Unknown'
                        }
                    ]
                });
                Ext.define('User', {
                    extend: 'Ext.data.Model',
                    associations: []
                });
            `,
            output: `
                Ext.define('User', {
                    extend: 'Ext.data.Model',
                    fields: [
                        'name', 'email',
                        {
                            name: 'age',
                            type: 'int',
                            allowNull: true
                        },
                        {
                            name: 'gender',
                            type: 'abc',
                            defaultValue: 'Unknown'
                        }
                    ]
                });
                Ext.define('User', {
                    extend: 'Ext.data.Model',
                    associations: []
                });
            `,
            errors: [
                { message: /Usage of deprecated config 'useNull'.*/ },
                { message: /Usage of deprecated config 'associations'.*/ }
            ]
        },
        {
            settings: {
                extjs: {
                    fromVersion: '4.1',
                    toVersion: '7.9.0'
                }
            },
            code: `
                Ext.define('MyCustomApp.Application', {
                    name: 'MyCustomApp',
                    extend: 'Ext.app.Application',
                    enableQuickTips: true
                });

                Ext.create({
                    xclass: 'Ext.app.Application',
                    name: 'MyCustomApp',
                    enableQuickTips: true
                });

                var className = 'Ext.app.Application'
                Ext.create({
                    xclass: className,
                    name: 'MyCustomApp',
                    enableQuickTips: true
                });
            `,
            output: `
                Ext.define('MyCustomApp.Application', {
                    name: 'MyCustomApp',
                    extend: 'Ext.app.Application',
                    quickTips: true
                });

                Ext.create({
                    xclass: 'Ext.app.Application',
                    name: 'MyCustomApp',
                    quickTips: true
                });

                var className = 'Ext.app.Application'
                Ext.create({
                    xclass: className,
                    name: 'MyCustomApp',
                    quickTips: true
                });
            `,
            errors: [
                { message: /Usage of deprecated config 'enableQuickTips' found for 'Ext.app.Application'.*/ },
                { message: /Usage of deprecated config 'enableQuickTips' found for 'Ext.app.Application'.*/ },
                { message: /Usage of deprecated config 'enableQuickTips' found for 'Ext.app.Application'.*/ }
            ]
        },
        {
            settings: {
                extjs: {
                    fromVersion: 4.1,
                    toVersion: '7.9.0'
                }
            },
            code: `
                Ext.define('MyCustomComponent', {
                    extend: 'Ext.Component',

                    autoScroll: true,
                    autoLoad: 'resources/html/MyCustomComponent.html',

                    overflowX: function () {
                        return this.callParent();
                    },

                    // override with a FunctionalExpression
                    overflowY: function () {
                        return this.callParent();
                    },

                    // override with MemberExpression
                    overflowY: Ext.emptyFn,

                    // override with ConditionalExpression
                    renderSelectors: supportsIndexOf ? function(array, item) {
                        return 1;
                    } : function(array, item) {
                        return 2;
                    }
                });

                Ext.create('Ext.Container', {
                    autoLoad: {
                        url: 'resources/html/MyCustomComponent.html'
                    }
                });
                Ext.define('Ext4App.view.AutoLoad', {
                    extend: 'Ext.tab.Panel',
                    items: [
                        {
                            title: 'Tab 1',
                            // TODO - an issue should be reported about the deprecated autoScroll config but it is not
                            // once support is added for defaultType then the issue will be reported
                            autoScroll: true
                        }
                    ]
                });
            `,
            output: `
                Ext.define('MyCustomComponent', {
                    extend: 'Ext.Component',

                    scrollable: true,
                    loader: {url: 'resources/html/MyCustomComponent.html', autoLoad: true},

                    scrollable: function () {
                        return this.callParent();
                    },

                    // override with a FunctionalExpression
                    scrollable: function () {
                        return this.callParent();
                    },

                    // override with MemberExpression
                    scrollable: Ext.emptyFn,

                    // override with ConditionalExpression
                    childEls: supportsIndexOf ? function(array, item) {
                        return 1;
                    } : function(array, item) {
                        return 2;
                    }
                });

                Ext.create('Ext.Container', {
                    loader: {
                        url: 'resources/html/MyCustomComponent.html'
                    }
                });
                Ext.define('Ext4App.view.AutoLoad', {
                    extend: 'Ext.tab.Panel',
                    items: [
                        {
                            title: 'Tab 1',
                            // TODO - an issue should be reported about the deprecated autoScroll config but it is not
                            // once support is added for defaultType then the issue will be reported
                            autoScroll: true
                        }
                    ]
                });
            `,
            errors: [
                { message: /Usage of deprecated config 'autoScroll' found for 'Ext.Component'.*/ },
                { message: /Usage of deprecated config 'autoLoad' found for 'Ext.Component'.*/ },
                { message: /Usage of deprecated config 'overflowX' found for 'Ext.Component'.*/ },
                { message: /Usage of deprecated config 'overflowY' found for 'Ext.Component'.*/ },
                { message: /Usage of deprecated config 'overflowY' found for 'Ext.Component'.*/ },
                { message: /Usage of deprecated config 'renderSelectors' found for 'Ext.Component'.*/ },
                { message: /Usage of deprecated config 'autoLoad' found for 'Ext.Container'.*/ }
            ]
        },
        {
            settings: {
                extjs: {
                    fromVersion: '4.0',
                    toVersion: '7.9.0'
                }
            },
            code: `
                Ext.define('MyCustomComponent', {
                    extend: 'Ext.Component',
                    autoScroll: true,
                    autoLoad: 'resources/html/MyCustomComponent.html'
                });

                Ext.create('Ext.Container', {
                    autoScroll: true,
                    autoLoad: {
                        url: 'resources/html/MyCustomComponent.html'
                    }
                });
                Ext.define('Ext4App.view.AutoLoad', {
                    extend: 'Ext.tab.Panel',
                    autoScroll: true,
                    items: [
                        {
                            xtype: 'component',
                            title: 'Tab 1',
                            autoScroll: true
                        }
                    ]
                });
            `,
            output: `
                Ext.define('MyCustomComponent', {
                    extend: 'Ext.Component',
                    scrollable: true,
                    loader: {url: 'resources/html/MyCustomComponent.html', autoLoad: true}
                });

                Ext.create('Ext.Container', {
                    scrollable: true,
                    loader: {
                        url: 'resources/html/MyCustomComponent.html'
                    }
                });
                Ext.define('Ext4App.view.AutoLoad', {
                    extend: 'Ext.tab.Panel',
                    scrollable: true,
                    items: [
                        {
                            xtype: 'component',
                            title: 'Tab 1',
                            scrollable: true
                        }
                    ]
                });
            `,
            errors: [
                { message: /Usage of deprecated config 'autoScroll' found for 'Ext.Component'.*/ },
                { message: /Usage of deprecated config 'autoLoad' found for 'Ext.Component'.*/ },
                { message: /Usage of deprecated config 'autoScroll' found for 'Ext.Container'.*/ },
                { message: /Usage of deprecated config 'autoLoad' found for 'Ext.Container'.*/ },
                { message: /Usage of deprecated config 'autoScroll' found for 'Ext.tab.Panel'.*/ },
                { message: /Usage of deprecated config 'autoScroll' found for 'Ext.Component'.*/ }
            ]
        }
        // TODO - this currently does not report any issues on the autoScroll config
        // but it should and the issue is that we need to add support for 'defaultType'
        // for a config that does not have an xtype or xclass config
        // {
        //     settings: {
        //         extjs: {
        //             fromVersion: '4.0',
        //             toVersion: '7.4.0'
        //         }
        //     },
        //     code: `
        //         Ext.define('MyCustomTabPanel', {
        //             extend: 'Ext.tab.Panel',
        //             items: [{
        //                 title: 'Tab 1',
        //                 autoScroll: true
        //             }]
        //         });
        //         Ext.define('MyCustomTabPanel', {
        //             extend: 'Ext.tab.Panel',
        //             defaults: {
        //                 xtype: 'component'
        //             },
        //             items: [{
        //                 title: 'Tab 1',
        //                 autoScroll: true
        //             }]
        //         });
        //     `,
        //     output: `
        //         Ext.define('MyCustomTabPanel', {
        //             extend: 'Ext.tab.Panel',
        //             items: [{
        //                 title: 'Tab 1',
        //                 scrollable: true
        //             }]
        //         });
        //         Ext.define('MyCustomTabPanel', {
        //             extend: 'Ext.tab.Panel',
        //             defaults: {
        //                 xtype: 'component'
        //             },
        //             items: [{
        //                 title: 'Tab 1',
        //                 scrollable: true
        //             }]
        //         });
        //     `,
        //     errors: [
        //         { message: /Usage of deprecated config 'autoScroll' found for 'Ext.panel.Panel'.*/ },
        //         { message: /Usage of deprecated config 'autoScroll' found for 'Ext.Component'.*/ }
        //     ]
        // }
    ]
});
